/**
 * Las imágenes de marca del correo, embebidas como base64 y adjuntas por CID.
 *
 * Van dentro del código a propósito: un correo no puede depender de la URL de
 * un ambiente (el mismo build sirve a staging y producción) y los clientes de
 * correo bloquean imágenes remotas por defecto — las adjuntas por CID se
 * muestran siempre. Son PNG porque Gmail y Outlook no pintan SVG; salen de
 * `apps/web/src/assets` (logo blanco y personajes) rasterizados a 2x.
 */

export interface MailAsset {
  cid: string
  filename: string
  base64: string
}

const b64 = (parts: string[]): string => parts.join('')

